import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const out='/tmp/legendgirl-vegetacao-rios';await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/vegetacao-rios',{recursive:true});
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});
 for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await review.game.assetsReady;review.game.startDebugPhase('garden','NORMAL');const p=review.game.state.toyRoomInstance.instance.garden;for(let i=0;i<200&&!p.ready;i++)await new Promise(r=>setTimeout(r,50));if(!p.ready)throw Error(p.error||'Artes não carregaram');review.game.setPaused(true);window.vqa={phase:p};})()`);
 const comparison=await evaluate(`(async()=>{
  const {GardenRenderer}=await import('/docs/diario-ia/qa/vegetacao-rios/renderer-antes.mjs');const {createGardenState}=await import('/src/js/garden/GardenSimulation.js');const {GARDEN_PLATFORM_BY_ID,gardenSurfaceY}=await import('/src/js/garden/GardenLevel.js');
  const p=vqa.phase,canvas=p.canvas;canvas.width=1280;canvas.height=800;const before=new GardenRenderer(canvas);await before.load();const states=[];
  for(const x of [1900,2700,13500]){const s=createGardenState();s.stage='RUNNING';s.time=10;Object.assign(s.player,{x,y:540,terrain:'soil'});states.push(s);}
  const stat=a=>{const b=[...a].sort((a,b)=>a-b);return{media:a.reduce((a,b)=>a+b,0)/a.length,p95:b[Math.floor(b.length*.95)],maximo:b.at(-1),amostras:b.length};};
  let gpu='indisponível';try{const c=document.createElement('canvas'),gl=c.getContext('webgl'),e=gl?.getExtension('WEBGL_debug_renderer_info');gpu=e?gl.getParameter(e.UNMASKED_RENDERER_WEBGL):'sem extensão';gl?.getExtension('WEBGL_lose_context')?.loseContext();}catch{}
  const result={gpu,cenarios:[]};
  for(let i=0;i<states.length;i++)for(const [nome,r]of [['anterior',before],['atual',p.renderer]]){
   const timings=[],intervals=[];let last;for(let n=0;n<180;n++){const stamp=await new Promise(requestAnimationFrame);if(last&&n>20)intervals.push(stamp-last);last=stamp;states[i].time+=1/60;const start=performance.now();r.render(states[i]);if(n>20)timings.push(performance.now()-start);}
   result.cenarios.push({x:states[i].player.x,versao:nome,desenhoMs:stat(timings),intervaloMs:stat(intervals)});
  }
  before.destroy();return result;
 })()`);console.log('COMPARAÇÃO',JSON.stringify(comparison));
 // Registra cenas nativas em três proporções; nunca usa a imagem conceitual como evidência.
 for(const [name,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:height>width});
  for(const [label,x]of [['vegetacao',1900],['rio',2700],['morro',13500]]){
   const data=await evaluate(`(async()=>{const {createGardenState}=await import('/src/js/garden/GardenSimulation.js'),{gardenPlatforms}=await import('/src/js/garden/GardenLevel.js'),{gardenContactHeight}=await import('/src/js/garden/GardenContact.js');const p=vqa.phase;p.canvas.width=${width};p.canvas.height=${height};const s=createGardenState();s.stage='RUNNING';s.time=10;const support=gardenPlatforms(10,s,${x}).find(v=>${x}>=v.x&&${x}<=v.x+v.w);Object.assign(s.player,{x:${x},onGround:!!support,support:support?.id,terrain:support?.type??'soil'});s.player.y=support?gardenContactHeight(support,s.player,${x}):500;s.fairy.x=${x}+30;s.fairy.y=s.player.y-120;p.state=s;p.render();return p.canvas.toDataURL();})()`);
   const bytes=Buffer.from(data.split(',')[1],'base64');await writeFile(out+'/'+name+'-'+label+'.png',bytes);await writeFile('docs/diario-ia/qa-resultados/vegetacao-rios/'+name+'-'+label+'.png',bytes);
  }
 }
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 // Planeja comandos válidos antes da medição para não atribuir custo do piloto ao jogo.
 const planned=await evaluate(`(async()=>{const {createGardenState,stepGarden,retryGarden}=await import('/src/js/garden/GardenSimulation.js'),{createPilot}=await import('/docs/diario-ia/qa/jardim-v2/piloto.mjs');const s=createGardenState();let pilot=createPilot(),retries=0;const inputs=[];for(let tick=0;tick<40000&&s.stage!=='COMPLETE';tick++){const input=pilot(s);stepGarden(s,input,1/60);let retry=false;if(s.stage==='GAME_OVER'){if(++retries>3)throw Error('Excesso de tentativas');retryGarden(s);pilot=createPilot();retry=true;}inputs.push({input,retry});if(tick%600===0)await new Promise(r=>setTimeout(r,0));}if(s.stage!=='COMPLETE')throw Error('Piloto não chegou');vqa.inputs=inputs;return{quadros:inputs.length,retries};})()`);console.log('COMANDOS',JSON.stringify(planned));
 await evaluate(`(async()=>{const {createGardenState,stepGarden,retryGarden}=await import('/src/js/garden/GardenSimulation.js');const p=vqa.phase;p.canvas.width=1280;p.canvas.height=800;p.state=createGardenState();vqa.result={desenho:[],intervalos:[],capturas:[],retries:0};vqa.index=0;vqa.nextX=0;vqa.done=false;let last,skip=false;
  function frame(stamp){try{const r=vqa.result,t=vqa.inputs[vqa.index++];if(!t){r.stage=p.state.stage;r.x=p.state.player.x;vqa.done=true;return;}stepGarden(p.state,t.input,1/60);if(t.retry){retryGarden(p.state);r.retries++;}const start=performance.now();p.render();const duration=performance.now()-start;if(vqa.index>120&&!skip){r.desenho.push(duration);if(last)r.intervalos.push(stamp-last);}last=stamp;skip=false;
   if(p.state.player.x>=vqa.nextX){r.capturas.push({x:p.state.player.x,estado:structuredClone(p.state),data:p.canvas.toDataURL()});vqa.nextX=p.state.player.x+1500;skip=true;}
   requestAnimationFrame(frame);
  }catch(e){vqa.failure=String(e);vqa.done=true;}}requestAnimationFrame(frame);
 })()`);
 let done=false;
 for(let i=0;i<750;i++){await new Promise(r=>setTimeout(r,1000));if(i%30===0)console.log('REPRODUÇÃO',await evaluate('JSON.stringify({quadro:vqa.index,x:Math.round(vqa.phase.state.player.x),stage:vqa.phase.state.stage})'));if(await evaluate('vqa.done')){done=true;break;}}
 assert.ok(done,'Reprodução concluiu no prazo');assert.ok(!await evaluate('vqa.failure'),'Sem falha de execução');
 const result=await evaluate(`(()=>{const r=vqa.result,stat=a=>{const b=[...a].sort((a,b)=>a-b);return{media:a.reduce((a,b)=>a+b,0)/a.length,p95:b[Math.floor(b.length*.95)],p99:b[Math.floor(b.length*.99)],maximo:b.at(-1),amostras:b.length,acima25ms:a.filter(x=>x>25).length,acima50ms:a.filter(x=>x>50).length};};return{stage:r.stage,x:r.x,retries:r.retries,desenhoMs:stat(r.desenho),intervaloMs:stat(r.intervalos),capturas:r.capturas.length};})()`);
 assert.equal(result.stage,'COMPLETE','Reprodução física chegou ao piquenique');
 const count=result.capturas;
 for(let i=0;i<count;i++){const capture=await evaluate('vqa.result.capturas['+i+']');const name='percurso-'+String(i).padStart(2,'0');await writeFile(out+'/'+name+'.png',Buffer.from(capture.data.split(',')[1],'base64'));delete capture.data;await writeFile(out+'/'+name+'.json',JSON.stringify(capture));}
 await writeFile(out+'/resultado.json',JSON.stringify({comparison,planned,result},null,2));await writeFile('docs/diario-ia/qa-resultados/vegetacao-rios/resultado.json',JSON.stringify({comparison,planned,result},null,2));console.log('RESULTADO',JSON.stringify(result));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
